// Material-, Produktions- und Absatzwirtschaft – erstellt aus den Lehrgangsskripten (eigene Formulierungen)
FRAGEN.push(
  // ===== Wo. 09: Produktlebenszyklus =====
  { id: 'mpa-plz-01', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'karte',
    frage: 'Nenne die fünf Phasen des Produktlebenszyklus und beschreibe kurz den Verlauf von Umsatz und Gewinn.',
    antwort: 'Einführung: Umsatz niedrig, Gewinn meist negativ (hohe Werbe-, Entwicklungs- und Vertriebskosten).\nWachstum: Umsatz steigt schnell, die Gewinnzone wird erreicht.\nReife: Umsatzwachstum verlangsamt sich, Umsatz bleibt hoch, der Gewinn erreicht seinen Höhepunkt.\nSättigung: Umsatz beginnt zu sinken, Markt weitgehend ausgeschöpft, Gewinn geht zurück.\nRückgang: Umsatz und Gewinn sinken deutlich, das Produkt wird verdrängt oder durch eine Innovation ersetzt.' },
  { id: 'mpa-plz-02', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'mc',
    frage: 'In welcher Phase des Produktlebenszyklus erreicht der Gewinn laut Skript seinen Höhepunkt?',
    optionen: ['Reifephase', 'Einführungsphase', 'Wachstumsphase', 'Rückgangsphase'],
    richtig: 0,
    erklaerung: 'In der Reifephase verlangsamt sich das Umsatzwachstum, der Umsatz bleibt aber hoch und der Gewinn ist am höchsten. Ziel ist, die Position zu verteidigen, z. B. mit Produktpflege, Kundenbindung oder einem neuen Design.' },
  { id: 'mpa-plz-03', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'karte',
    frage: 'Welche Ziele und typischen Maßnahmen gehören zur Einführungs- und zur Wachstumsphase?',
    antwort: 'Einführung – Ziel: Bekanntheit aufbauen, erste Kunden gewinnen. Maßnahmen: intensive Werbung, Einführungsrabatte, Schulung des Verkaufspersonals.\nWachstum – Ziel: Marktanteile sichern, denn die Konkurrenz beginnt zu kopieren oder Alternativen anzubieten. Maßnahmen: Ausbau der Produktion, Preisanpassung, stärkere Differenzierung.' },
  { id: 'mpa-plz-04', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'karte',
    frage: 'Was ist in der Sättigungs- und in der Rückgangsphase typisch, und welche Maßnahmen passen?',
    antwort: 'Sättigung: Umsatz sinkt, Markt ausgeschöpft, Gewinn geht zurück, Konkurrenzdruck steigt. Maßnahmen: Preisnachlässe, Sonderaktionen, Serviceangebote, um die Phase zu verlängern.\nRückgang: Umsatz und Gewinn sinken deutlich. Es muss entschieden werden: Produkt vom Markt nehmen oder relaunchen? Maßnahmen: Ausverkauf, Produktion einstellen, ggf. Relaunch mit überarbeitetem Konzept.' },
  { id: 'mpa-plz-05', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'mc',
    frage: 'Ein Produkt ist seit Jahren beliebt, das Unternehmen ist Marktführer, aber es kommen immer mehr Wettbewerber auf den Markt. Welche Phase liegt laut Prüfungslösung (F2022) vor?',
    optionen: ['Reifephase', 'Einführungsphase', 'Rückgangsphase', 'Wachstumsphase'],
    richtig: 0,
    erklaerung: 'Marktführerschaft, Beliebtheit bei den Kunden und eine stetig steigende Zahl an Wettbewerbern sprechen für die Reifephase. Als Maßnahme gegen Marktanteilsverluste wird ein Produkt-Relaunch empfohlen (neue Eigenschaften, Designelemente).' },
  { id: 'mpa-plz-06', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'karte',
    frage: 'Prüfungsstil (F2018): Nenne Kritikpunkte am Modell des Produktlebenszyklus und ein Produkt, auf das es schlecht passt.',
    antwort: 'Kritik: vereinfachtes Abbild der Realität, betrachtet nur Umsatz bzw. Gewinn im Zeitablauf. Maßnahmen der Wettbewerber und die eigene Produkt-, Kontrahierungs-, Distributions- und Kommunikationspolitik bleiben unberücksichtigt. Die möglichen Verläufe sind so unterschiedlich, dass ein Modell sie nicht alle beschreiben kann. Externe Ereignisse (bessere Konkurrenzprodukte, veränderte Kaufkraft) fehlen.\nSchlecht anwendbar: Produkte mit sehr langem Verkaufszeitraum, z. B. die Kartoffel (über 100 Jahre), oder mit sehr kurzem Verkaufszeitraum.' },
  { id: 'mpa-plz-07', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'karte',
    frage: 'Prüfungsstil (F2018): Ein Relaunch hatte bei Produkt 1 nur kurz und gering Erfolg, bei Produkt 2 verlängerte er den Verkaufszeitraum deutlich. Nenne mögliche Gründe.',
    antwort: 'Produkt 1 (geringer Erfolg): entspricht nicht mehr dem Stand der Technik; der Wettbewerb verkauft zeitgleich ein erfolgreicheres Produkt.\nProdukt 2 (erfolgreich): in der Zielgruppe erfolgreich beworben; konstruktiv an geänderte Anforderungen der Zielgruppe angepasst; in einer neuen Zielgruppe bekannt gemacht und beworben.' },
  { id: 'mpa-plz-08', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'karte',
    frage: 'Prüfungsstil (F2022): Welche Marketingmaßnahme passt laut Lösung zu welcher Phase des Produktlebenszyklus?',
    antwort: 'Einführung: Kommunikationspolitik – Werbung, PR und Verkaufsförderung begleiten den Produktstart.\nWachstum: Preis- und Konditionenpolitik, um Konkurrenten mit Me-too-Produkten vom Markteintritt abzuhalten.\nReife: Kommunikationspolitik mit Erhaltungswerbung, um die Nachfrage zu halten.\nSättigung: Produktpolitik – Produktdiversifikation oder Relaunch, um den Rückgang hinauszuzögern.\nDegeneration: Produktpolitik bereitet die Liquidation vor; das Produkt bleibt, solange es positive Deckungsbeiträge bringt.' },
  { id: 'mpa-plz-09', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'karte',
    frage: 'Prüfungsstil (F2020): Welches Konzept für die Zusammenarbeit mit Lieferanten von Zukaufteilen passt zu welcher Lebenszyklusphase?',
    antwort: 'Einführung: Single Sourcing – geringe Mengen bei einem Lieferanten bündeln, z. B. für Rabatte.\nWachstum: Dual oder Multiple Sourcing – ein Lieferant allein schafft die steigende Menge evtl. nicht; zusätzlich Wettbewerb um Qualität und Preis.\nReife: fertigungssynchrone Anlieferung, weil der Bedarf gut planbar ist – senkt Lagerkosten.\nSättigung: Konsignationslager mit einem Zulieferer, der den Bestand an den sinkenden Bedarf anpasst.\nRückgang: Materialbedarf wieder bei einem Zulieferer bündeln und die Ersatzteilversorgung nach Verkaufsende sicherstellen.' },
  { id: 'mpa-plz-10', fach: 'mpa', thema: 'Produktlebenszyklus', typ: 'mc',
    frage: 'Ein neues Produkt wird bald eingeführt, die Mengen sind noch gering. Welche Beschaffungsstrategie empfiehlt die Prüfungslösung (F2020) für die Einführungsphase?',
    optionen: ['Single Sourcing', 'Multiple Sourcing', 'Konsignationslager', 'Fertigungssynchrone Anlieferung'],
    richtig: 0,
    erklaerung: 'In der Einführungsphase lohnt es sich, die noch kleinen Mengen bei einem Lieferanten zu konzentrieren (Rabatte). Multiple Sourcing passt zur Wachstumsphase, die fertigungssynchrone Anlieferung zur Reife, das Konsignationslager zur Sättigung.' },

  // ===== Wo. 09: Verträge =====
  { id: 'mpa-ve-01', fach: 'mpa', thema: 'Vertragspolitik', typ: 'karte',
    frage: 'Welche drei Entscheidungen umfasst die Vertragspolitik? Nenne je Beispiele.',
    antwort: 'Wahl der Vertragsart: Kaufvertrag, Werkvertrag, Dienstleistungsvertrag, Mietvertrag.\nWahl der Vertragsform: Rahmenvertrag, Konsignationslagervertrag, Abrufvertrag, Sukzessivliefervertrag.\nArt der Vertragsbindung: langfristig, kurzfristig, Spotgeschäfte.' },
  { id: 'mpa-ve-02', fach: 'mpa', thema: 'Vertragsentstehung', typ: 'karte',
    frage: 'Wie kommt ein Vertrag zustande, und in welcher Form kann er geschlossen werden?',
    antwort: 'Durch zwei übereinstimmende Willenserklärungen: Antrag (beim Kaufvertrag = Angebot) und Annahme.\nForm: mündlich, fernmündlich, schriftlich, über moderne Kommunikationsmittel oder durch konkludentes (schlüssiges) Verhalten.' },
  { id: 'mpa-ve-03', fach: 'mpa', thema: 'Vertragsfreiheit', typ: 'karte',
    frage: 'Was bedeutet Vertragsfreiheit, und wo liegen ihre Grenzen?',
    antwort: 'Abschlussfreiheit: Mit wem schließe ich einen Vertrag?\nInhaltsfreiheit: Was wird vereinbart?\nGrenzen: Verträge dürfen nicht gegen bestehende Gesetze, nicht gegen Treu und Glauben verstoßen und nicht sittenwidrig sein.' },
  { id: 'mpa-ve-04', fach: 'mpa', thema: 'Vertragsarten', typ: 'mc',
    frage: 'Ein Ingenieurbüro sichert zu, ein technisches Problem vollständig zu lösen. Welche Vertragsart liegt vor (H2020)?',
    optionen: ['Werkvertrag', 'Dienstvertrag', 'Kaufvertrag', 'Lizenzvertrag'],
    richtig: 0,
    erklaerung: 'Beim Werkvertrag schuldet der Auftragnehmer einen Erfolg (Herstellung oder Veränderung einer Sache). Beim Dienstvertrag wird nur die Leistung geschuldet, ohne Erfolgsgarantie – bezahlt wird auch, wenn der Erfolg ausbleibt.' },
  { id: 'mpa-ve-05', fach: 'mpa', thema: 'Vertragsarten', typ: 'karte',
    frage: 'Grenze Kauf-, Werk-, Werklieferungs- und Dienstvertrag voneinander ab.',
    antwort: 'Kaufvertrag: entgeltliche Veräußerung von Sachen und Rechten, Ziel Eigentumsübertragung. Verkäufer übergibt mangelfrei, Käufer nimmt ab und zahlt.\nWerkvertrag: entgeltliche Herstellung oder Veränderung einer Sache, geschuldet ist der Erfolg; der Auftraggeber zahlt bei Erfolg und nimmt das Werk ab.\nWerklieferungsvertrag: Lieferung herzustellender beweglicher Sachen (z. B. Motoren, die beim Auftraggeber eingebaut werden).\nDienstvertrag: entgeltliche Leistung eines Dienstes ohne geschuldeten Erfolg.' },
  { id: 'mpa-ve-06', fach: 'mpa', thema: 'Vertragsarten', typ: 'karte',
    frage: 'Wodurch unterscheiden sich Miet-, Leih- und Pachtvertrag?',
    antwort: 'Miete: entgeltliche Nutzungsüberlassung einer Sache; Mieter wird Besitzer und zahlt Mietzins.\nLeihe: unentgeltliche Überlassung zum Gebrauch (der umgangssprachliche „Fahrradverleih“ gegen Geld ist rechtlich Miete).\nPacht: entgeltliche Nutzungsüberlassung mit Fruchtgenuss – der Pächter darf die Sache nutzen und wird Eigentümer des Ertrags; er zahlt Pachtzins.' },
  { id: 'mpa-ve-07', fach: 'mpa', thema: 'Vertragsarten', typ: 'mc',
    frage: 'Beim Leasingvertrag gilt laut Skript:',
    optionen: ['Der Leasingnehmer erhält das Nutzungsrecht und trägt Untergangsgefahr und Instandhaltungskosten', 'Der Leasinggeber trägt alle Instandhaltungskosten', 'Der Leasingnehmer wird sofort Eigentümer', 'Die Nutzung ist unentgeltlich'],
    richtig: 0,
    erklaerung: 'Leasing ist eine entgeltliche Nutzungsüberlassung. Der Leasingnehmer wird Besitzer, zahlt Leasingraten und trägt die Gefahr des Untergangs und die Instandhaltung. Der Leasinggeber überträgt das Nutzungsrecht und erhält die Raten (ggf. Sonderzahlung).' },
  { id: 'mpa-ve-08', fach: 'mpa', thema: 'Vertragsarten', typ: 'karte',
    frage: 'Was regeln Lizenzvertrag und Kooperationsvertrag?',
    antwort: 'Lizenzvertrag: Übertragung von Nutzungsrechten an Patenten, Mustern, Marken, Software. Der Lizenzgeber erlaubt die gewerbliche Nutzung und erhält Lizenzgebühren – der Lizenznehmer zahlt auch, wenn er das Recht nicht nutzt.\nKooperation: auf Zusammenarbeit gerichteter Vertrag (z. B. gemeinsame Büronutzung, Werbung, Markterschließung). Die Partner bleiben rechtlich selbstständig. Formen: Arbeits-/Interessengemeinschaften, Kartelle, Konsortien.' },
  { id: 'mpa-ve-09', fach: 'mpa', thema: 'Spezielle Kaufverträge', typ: 'karte',
    frage: 'Erkläre bürgerlichen Kauf, einseitigen und zweiseitigen Handelskauf sowie Stück- und Gattungskauf.',
    antwort: 'Bürgerlicher Kauf: beide Nichtkaufleute bzw. kein Handelsgeschäft.\nEinseitiger Handelskauf: Kaufmann (Handelsgeschäft) + Nichtkaufmann.\nZweiseitiger Handelskauf: Kaufmann + Kaufmann, für beide ein Handelsgeschäft.\nStückkauf: nicht vertretbare, einmalige Sache.\nGattungskauf: vertretbare Sache, mehrfach vorhanden.' },
  { id: 'mpa-ve-10', fach: 'mpa', thema: 'Spezielle Kaufverträge', typ: 'karte',
    frage: 'Was kennzeichnet Terminkauf, Kommissionskauf, Verbrauchsgüterkauf und Kauf auf Probe?',
    antwort: 'Terminkauf: Lieferung zu einem vereinbarten Termin oder innerhalb einer Frist.\nKommissionskauf: Der Käufer zahlt erst, wenn er die Sache selbst weiterverkauft hat.\nVerbrauchsgüterkauf (§ 474 BGB): Ein Verbraucher kauft eine bewegliche Sache von einem Unternehmer.\nKauf auf Probe: Kaufvertrag unter der Bedingung, dass der Käufer die Ware billigt.' },
  { id: 'mpa-ve-11', fach: 'mpa', thema: 'Spezielle Kaufverträge', typ: 'mc',
    frage: 'Bei welchem Vertrag stehen Preise, Mengen, Zeitraum UND die genauen Anliefertermine von Anfang an fest?',
    optionen: ['Sukzessivliefervertrag', 'Abrufvertrag', 'Rahmenvertrag', 'Spezifikationskauf'],
    richtig: 0,
    erklaerung: 'Beim Sukzessivliefervertrag ist alles inklusive der Liefertermine festgelegt. Beim Abrufvertrag sind Preise, Mengen und Zeitraum fest, die einzelnen Abrufe erfolgen individuell. Beim Rahmenvertrag ist alles außer den Mengen festgelegt.' },
  { id: 'mpa-ve-12', fach: 'mpa', thema: 'Spezielle Kaufverträge', typ: 'karte',
    frage: 'Was sind Rahmenvertrag, Spezifikationskauf, Bedarfsdeckungsvertrag und Konsignationslagervertrag?',
    antwort: 'Rahmenvertrag: alle Vertragspunkte außer den Mengen sind festgelegt. Rahmenvertragsquote = Anzahl Rahmenverträge ÷ Anzahl Verträge gesamt.\nSpezifikationskauf: Rahmenvereinbarung über Art, Menge und Grundpreis; Einzelheiten erst beim Abruf.\nBedarfsdeckungsvertrag: Bindung an einen Lieferanten über den Gesamt- oder Teilbedarf eines Gutes.\nKonsignationslagervertrag: Vorräte im eigenen Lager bleiben bis zur Entnahme Eigentum des Lieferanten.' },
  { id: 'mpa-ve-13', fach: 'mpa', thema: 'Spezielle Kaufverträge', typ: 'karte',
    frage: 'Prüfungsstil (H2019): Nenne Vorteile von Rahmenlieferungsverträgen gegenüber Einzelverträgen.',
    antwort: 'Die Materialversorgung ist langfristig gesichert.\nWeniger Verhandlungsaufwand.\nLieferanten können langfristiger planen.\nDurch die vereinbarten Mengen sind höhere Rabatte bzw. niedrigere Preise möglich.\n(Laut Skript außerdem: Daten liegen im System vor und erleichtern Einkauf und Rechnungsprüfung.)' },
  { id: 'mpa-ve-14', fach: 'mpa', thema: 'Prüfungsaufgabe', typ: 'karte', art: 'rechnen',
    frage: 'Prüfungsstil (H2019): Rahmenvertrag: 80 USD je Stück, darin 340 g Kupfer, Kupferpreis bei Abschluss 7.200 USD/t, Preisgleitklausel. Bei Lieferung von 4.500 Stück kostet Kupfer 7.800 USD/t, Kurs 0,73 €/USD. Vorjahreskosten 270.000 €. Materialkosten in €?',
    antwort: 'Kupfer bei Abschluss: 7,20 USD/kg × 0,34 kg = 2,448 USD/Stück\nKupfer bei Lieferung: 7,80 USD/kg × 0,34 kg = 2,652 USD/Stück\nStückpreis neu = 80 − 2,448 + 2,652 = 80,204 USD\n80,204 × 0,73 = 58,54892 € × 4.500 = 263.470,14 €\nGegenüber dem Vorjahr (270.000 €) ein Kostenvorteil von 6.529,86 €.' },
  { id: 'mpa-ve-15', fach: 'mpa', thema: 'Gewährleistung', typ: 'karte',
    frage: 'Unterscheide Gewährleistung, Garantie und Kulanz.',
    antwort: 'Gewährleistung (Mängelhaftung): gesetzliche Pflicht des Verkäufers, mangelfreie Ware zu liefern; zeitlich befristet; Käufer hat Anspruch auf Reparatur, Ersatz oder Rücktritt.\nGarantie: freiwillige Zusatzleistung von Hersteller oder Händler, sichert eine bestimmte Haltbarkeit oder Funktion zu (z. B. 5 Jahre Rostfreiheit).\nKulanz: freiwilliges Entgegenkommen über gesetzliche und vertragliche Pflichten hinaus.\nMerksatz: Gewährleistung ist Pflicht, Garantie ist Versprechen, Kulanz ist Entgegenkommen.' },
  { id: 'mpa-ve-16', fach: 'mpa', thema: 'AGB', typ: 'karte',
    frage: 'Was sind AGB, was enthalten sie typischerweise, und wann werden sie Vertragsbestandteil (§ 305 BGB)?',
    antwort: 'Vorformulierte Vertragsbedingungen für viele Verträge; nur gültig, wenn nicht individuell ausgehandelt. Zweck: gesetzliche Vertragstypen ergänzen/anpassen, einheitliche Grundlage.\nTypische Inhalte: Gerichtsstand, Eigentumsvorbehalt, Haftung, Transportversicherung, Verpackung, Erfüllungsort, Gewährleistung.\nVoraussetzungen: Hinweis (ausdrücklich oder sichtbarer Aushang), Möglichkeit der Kenntnisnahme, Einverständnis.' },
  { id: 'mpa-ve-17', fach: 'mpa', thema: 'Erfüllungsort', typ: 'mc',
    frage: 'Bei welcher Schuld muss der Schuldner die Leistung am Wohnsitz des Gläubigers erbringen?',
    optionen: ['Bringschuld', 'Holschuld', 'Schickschuld', 'Bei keiner'],
    richtig: 0,
    erklaerung: 'Bringschuld: Erfüllung am Wohnsitz des Gläubigers, der Schuldner bringt die Leistung. Holschuld: am Wohnsitz des Schuldners, der Gläubiger holt ab. Schickschuld: am Wohnsitz des Schuldners zu erfüllen, der Schuldner versendet zum Gläubiger.' },
  { id: 'mpa-ve-18', fach: 'mpa', thema: 'Verpflichtungsgeschäft', typ: 'karte',
    frage: 'Prüfungsstil (F2023): Was sind Verpflichtungs- und Erfüllungsgeschäft? Nenne Inhalte des Erfüllungsgeschäfts.',
    antwort: 'Verpflichtungsgeschäft: Abschluss des Vertrags durch zwei Willenserklärungen (Angebot und Annahme).\nErfüllungsgeschäft: Die Beteiligten erfüllen die eingegangenen Pflichten.\nKäufer: Ware annehmen und Kaufpreis zahlen. Verkäufer: Ware mangelfrei liefern und Eigentum verschaffen.' },
  { id: 'mpa-ve-19', fach: 'mpa', thema: 'Kaufvertrag', typ: 'karte',
    frage: 'Prüfungsstil (F2023): Nenne Bestandteile (Inhalte) eines Kaufvertrags.',
    antwort: 'Z. B.: Art, Beschaffenheit und Güte der Ware, Menge, Preis, Verpackung, Versand, Lieferzeit, Zahlungsbedingungen, Erfüllungsort, Eigentumsvorbehalt, AGB.' },
  { id: 'mpa-ve-20', fach: 'mpa', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2021): Am 31.01. einigt man sich auf einer Messe mündlich über den Kauf einer Maschine („ca. sechs Wochen nach Vertragsschluss“). Am 02.02. folgt eine schriftliche Bestellung, am 04.02. die Auftragsbestätigung. Wann und wie kam der Vertrag zustande?',
    antwort: 'Am 31.01. mündlich durch die vertretungsberechtigten Mitarbeiter (Antrag unter Anwesenden, § 147 Abs. 1 BGB). Bestellung und Auftragsbestätigung haben keine Wirkung mehr auf das Zustandekommen.' },
  { id: 'mpa-ve-21', fach: 'mpa', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2021): Kein kalendermäßiger Liefertermin vereinbart. Die alte Maschine fällt am 25.03. aus; erst danach setzt der Käufer telefonisch eine Frist bis 26.03. Liegt Verzug vor, und gibt es Ansprüche wegen des Ausfalls?',
    antwort: 'Der Anruf am 25.03. ist eine Fristsetzung, die Lieferung wird am 26.03. fällig – danach liegt Verzug vor. Die Frist von einem Tag ist aber nicht angemessen.\nFür den Ausfall am 25.03. gibt es keinen Anspruch: Es war kein kalendermäßiger Termin vereinbart und zum Ausfallzeitpunkt noch keine Frist gesetzt. Der Schaden geht zulasten des Käufers.' },
  { id: 'mpa-ve-22', fach: 'mpa', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2020): Katalog verschickt → Privatperson bestellt per Postkarte → Versandhaus liefert versehentlich zwei kleinere Jalousien → Privatperson ruft an und bietet 90 € für beide → Mitarbeiter stimmt zu. Ordne zu: Willenserklärung? Antrag/Annahme? Form?',
    antwort: '1. Katalog: keine Willenserklärung.\n2. Bestellung per Postkarte: Antrag der Privatperson unter Abwesenden, schriftlich.\n3. Lieferung zweier Jalousien: Annahme unter Abänderung (bzw. neuer Antrag des Versandhauses) unter Abwesenden, konkludent.\n4. Vorschlag 90 €: Annahme unter Abänderung (bzw. neuer Antrag der Privatperson) unter Anwesenden, fernmündlich.\n5. Zustimmung: Annahme des Antrags unter Anwesenden, fernmündlich.' },
  { id: 'mpa-ve-23', fach: 'mpa', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (F2022): Nenne zwei Voraussetzungen für das Zustandekommen eines Vertrags, zwei Vertragsstörungen und je eine Absicherung dagegen.',
    antwort: 'Voraussetzungen: zwei inhaltlich übereinstimmende Willenserklärungen; beide Parteien voll geschäftsfähig (sonst nur mit Zustimmung).\nStörungen: Verzug (Liefer- oder Zahlungsverzug), qualitative Abweichung (Schlechtleistung, Qualitätsmangel).\nAbsicherung: Konventionalstrafe für verspätete Leistung; vereinbarter Entschädigungssatz in Euro für die Zeit der Nichtnutzung wegen Nachbesserung.' },
  { id: 'mpa-ve-24', fach: 'mpa', thema: 'Gewerblicher Rechtsschutz', typ: 'karte',
    frage: 'Prüfungsstil (H2020): Erläutere vier Möglichkeiten des gewerblichen Rechtsschutzes.',
    antwort: 'Marke bzw. Wort-Bild-Marke beim Bundespatentamt: muss sich von bestehenden Marken unterscheiden und darf keine rein beschreibende Angabe sein (z. B. „Obst“ für Äpfel).\nGebrauchsmuster: technische Erfindung, neu und gewerblich nutzbar; sachliche Voraussetzungen werden nicht geprüft.\nPatent: technische Erfindung, neu, erfinderische Leistung, gewerblich anwendbar; das Amt prüft im Einzelfall.\nGeschütztes Design: neue äußere Erscheinungsform (Form, Farbe, Gestalt) mit Eigenart.' },

  // ===== Wo. 09: Leistungsstörungen =====
  { id: 'mpa-ls-01', fach: 'mpa', thema: 'Leistungsstörungen', typ: 'karte',
    frage: 'Welche Leistungsstörungen im Kaufvertrag unterscheidet das Skript?',
    antwort: 'Unmöglichkeit (§§ 280 ff. BGB): Der Schuldner kann nicht leisten – anfänglich oder nachträglich.\nVerzug: Schuldnerverzug (Lieferung bzw. Zahlung erfolgt nicht, §§ 286 ff.) und Gläubigerverzug (Ware/Zahlung wird nicht oder nicht rechtzeitig angenommen, §§ 293 ff.).\nMangel: Sach- oder Rechtsmangel (§§ 434 f.).' },
  { id: 'mpa-ls-02', fach: 'mpa', thema: 'Leistungsstörungen', typ: 'karte',
    frage: 'Wann liegt ein Sachmangel nach § 434 BGB vor? Nenne Beispiele.',
    antwort: 'Ware hat nicht die vereinbarte Beschaffenheit, ist fehlerhaft oder weicht von einer zugesicherten Garantie ab.\nOhne ausdrückliche Vereinbarung: nicht für die vorgesehene oder gewöhnliche Nutzung geeignet, nicht übliche Beschaffenheit, Abweichung von der beworbenen Qualität.\nIm weiteren Sinne: unsachgemäße Montage, mangelhafte Montageanleitung („IKEA-Klausel“), Falschlieferung.' },
  { id: 'mpa-ls-03', fach: 'mpa', thema: 'Leistungsstörungen', typ: 'mc',
    frage: 'Auf einer gekauften Immobilie lastet eine Grundschuld, die der Käufer nicht akzeptieren muss. Das ist ein …',
    optionen: ['Rechtsmangel (§ 435 BGB)', 'Sachmangel (§ 434 BGB)', 'Gläubigerverzug', 'Fall der Unmöglichkeit'],
    richtig: 0,
    erklaerung: 'Ein Rechtsmangel liegt vor, wenn Dritte Rechte an der Kaufsache haben, z. B. Eigentumsvorbehalt eines anderen, Pfandrechte oder Grundschulden, Schutzrechte wie Patente oder eine Vermietung. Der Käufer kann dann Gewährleistungsrechte geltend machen.' },
  { id: 'mpa-ls-04', fach: 'mpa', thema: 'Mängelrechte', typ: 'karte',
    frage: 'Welche Rechte hat der Käufer bei Mängeln? Was ist vorrangig, was nachrangig?',
    antwort: 'Vorrangig, ohne Nachfrist: Nacherfüllung (Nachbesserung oder Ersatzlieferung) und Schadensersatz neben der Leistung.\nNachrangig, mit Nachfrist: Rücktritt vom Vertrag, Minderung, Schadensersatz neben der Leistung, Schadensersatz statt der Leistung, Ersatz vergeblicher Aufwendungen.' },
  { id: 'mpa-ls-05', fach: 'mpa', thema: 'Mängelrechte', typ: 'mc',
    frage: 'Welches Recht ist bei einem Mangel der Primäranspruch des Käufers?',
    optionen: ['Nacherfüllung', 'Rücktritt vom Vertrag', 'Minderung', 'Schadensersatz statt der Leistung'],
    richtig: 0,
    erklaerung: 'Zuerst muss dem Verkäufer die Nacherfüllung (Nachbesserung oder Ersatzlieferung) ermöglicht werden. Rücktritt, Minderung, Schadensersatz und Ersatz vergeblicher Aufwendungen sind Sekundäransprüche.' },
  { id: 'mpa-ls-06', fach: 'mpa', thema: 'Verjährung', typ: 'karte',
    frage: 'Welche Verjährungsfristen gelten bei Sachmängeln?',
    antwort: '30 Jahre: dingliche Rechte, im Grundbuch eingetragene Rechte.\n5 Jahre: Bauwerk bzw. Sache, die für ein Bauwerk verwendet wurde.\n3 Jahre: arglistig verschwiegene Mängel.\n2 Jahre: alle übrigen Mängel – Hauptfall bei mangelhafter Warenlieferung (Kaufmann muss nach HGB unverzüglich rügen).\n1 Jahr: gebrauchte Sachen beim Verbrauchsgüterkauf (Verkürzung möglich).' },
  { id: 'mpa-ls-07', fach: 'mpa', thema: 'Verjährung', typ: 'mc',
    frage: 'Wie lange beträgt die regelmäßige Verjährungsfrist, z. B. für Forderungen aus Kauf-, Werk- und Mietverträgen sowie Lohnforderungen?',
    optionen: ['3 Jahre', '2 Jahre', '10 Jahre', '30 Jahre'],
    richtig: 0,
    erklaerung: 'Die regelmäßige Verjährungsfrist beträgt 3 Jahre. 10 Jahre gelten für Ansprüche bei Rechten an einem Grundstück, 30 Jahre für rechtskräftig festgestellte Ansprüche, vollstreckbare Urkunden und Ansprüche aus Insolvenzverfahren.' },
  { id: 'mpa-ls-08', fach: 'mpa', thema: 'Rügepflicht', typ: 'karte',
    frage: 'Was verlangt die kaufmännische Untersuchungs- und Rügepflicht (§ 377 HGB), und wann gilt sie?',
    antwort: 'Der Käufer muss die Ware unverzüglich nach Ablieferung untersuchen (soweit im Geschäftsgang möglich) und erkannte Mängel unverzüglich, d. h. ohne schuldhaftes Zögern, anzeigen – die Untersuchung allein reicht nicht.\nGilt nur beim beidseitigen Handelsgeschäft, nicht bei Verbrauchergeschäften.\nWer schweigt oder zu spät rügt, verliert alle Gewährleistungsansprüche.' },
  { id: 'mpa-ls-09', fach: 'mpa', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2018): Eine Privatperson kauft einen Rasenmäher, der am nächsten Tag nicht funktioniert. Art des Mangels, Frist und Beweislast, Rechte?',
    antwort: 'Sachmangel: nicht die vertraglich vereinbarte Beschaffenheit.\nAnzeige innerhalb von zwei Jahren. Beweislastumkehr: In den ersten sechs Monaten muss der Verkäufer beweisen, dass die Sache bei Übergabe in Ordnung war, in den folgenden 18 Monaten der Käufer, dass sie es nicht war.\nRechte: primär Nacherfüllung (Nachbesserung oder Ersatzlieferung); sekundär Rücktritt, Minderung, Schadensersatz, Ersatz vergeblicher Aufwendungen.' },
  { id: 'mpa-ls-10', fach: 'mpa', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (H2017): Eine Molkerei GmbH ersteigert online bei der Müller GmbH Tischtücher in Rosa, geliefert werden weiße. Art des Mangels? Kann die Mängelhaftung ohne schriftliche Vereinbarung ausgeschlossen werden? Prüffrist? Verjährung?',
    antwort: 'Sachmangel (falsche Farbe, § 434 Abs. 3 BGB).\nNein: Die Mängelhaftung ist gesetzlich und nur mit schriftlicher Vereinbarung ausschließbar; die Form des Zustandekommens ist egal. Beim Verbrauchsgüterkauf besteht ein gesetzliches Verbot.\nPrüfung unverzüglich, weil beide Kaufleute sind (§ 377 HGB).\nVerjährung der Ansprüche nach zwei Jahren (§ 438 BGB).' },
  { id: 'mpa-ls-11', fach: 'mpa', thema: 'Produkthaftung', typ: 'karte',
    frage: 'Was regelt das Produkthaftungsgesetz?',
    antwort: 'Verschuldensunabhängige Haftung (Gefährdungshaftung): Der Hersteller haftet allein, weil das Produkt fehlerhaft ist – keine Schuldfrage nötig.\nSetzt die EG-Produkthaftungsrichtlinie um (einheitlicher Verbraucherschutz in der EU).\nGilt für Hersteller, Importeure und Händler bei Personen- und Sachschäden.\nDaneben: BGB-Gewährleistung (§ 438 ff.) und deliktische Haftung (§ 823 BGB) unabhängig von einem Vertrag.' },

  // ===== Wo. 09: Internationale Geschäfte =====
  { id: 'mpa-in-01', fach: 'mpa', thema: 'UN-Kaufrecht', typ: 'mc',
    frage: 'Wann gilt das UN-Kaufrecht (CISG)?',
    optionen: ['Automatisch bei internationalen Kaufverträgen zwischen Vertragsstaaten, außer es wird ausdrücklich ausgeschlossen', 'Nur wenn es ausdrücklich vereinbart wird', 'Nur innerhalb der EU', 'Nur bei Verbrauchergeschäften'],
    richtig: 0,
    erklaerung: 'Das CISG regelt Pflichten und Ansprüche von Importeuren und Exporteuren und gilt in allen Staaten, die es ratifiziert haben. Vorteile: einheitliche Vertragsgestaltung, Rechtssicherheit, keine einseitige Benachteiligung.' },
  { id: 'mpa-in-02', fach: 'mpa', thema: 'ICC-Schiedsgericht', typ: 'karte',
    frage: 'Was ist ICC-Arbitration, wie läuft sie ab, und welche Vor- und Nachteile hat sie?',
    antwort: 'Streitigkeiten werden statt vor einem staatlichen Gericht von einem neutralen Schiedsgericht nach den ICC-Regeln entschieden.\nAblauf: Schiedsklausel im Vertrag → Klage bei der ICC (Paris) → Parteien benennen Schiedsrichter → nicht öffentliches Verfahren → verbindlicher, weltweit vollstreckbarer Schiedsspruch.\nVorteile: Anerkennung in über 170 Ländern, Vertraulichkeit, fachkundige Richter, oft schneller, Parteien bestimmen Sprache, Ort und Richter mit.\nNachteile: höhere Kosten, keine Berufung.' },
  { id: 'mpa-in-03', fach: 'mpa', thema: 'Incoterms', typ: 'karte',
    frage: 'Was sind Incoterms, und was regeln sie?',
    antwort: 'Internationale Regeln der Internationalen Handelskammer (ICC) zur Auslegung von Lieferbedingungen im Außenhandel.\nSie regeln: Ort der Lieferung bzw. Gefahrenübergang (Transportrisiko), Verantwortung für Transport, Versicherung und Zoll sowie die Kostenverteilung (Fracht, Versicherung, Zölle).\nNicht geregelt: Zahlungsbedingungen, Gewährleistung, Zustandekommen des Vertrags.' },
  { id: 'mpa-in-04', fach: 'mpa', thema: 'Incoterms', typ: 'karte',
    frage: 'Prüfungsstil (F2018/F2021): Nenne Vorteile der Incoterms und einen Nachteil, wenn man darauf verzichtet.',
    antwort: 'Vorteile: keine Missverständnisse, weil alles in Abkürzungen verdichtet und von der ICC festgelegt ist; schnellere Vertragsabschlüsse und einfachere Verhandlungen; weniger Streitigkeiten; mehr Transparenz – jeder weiß vorher, welche Risiken und Kosten er trägt; internationaler Geltungsbereich; Versicherungen bieten passende Verträge an.\nNachteil ohne Incoterms: Es ist schwerer, passende Versicherungen abzuschließen.' },
  { id: 'mpa-in-05', fach: 'mpa', thema: 'Incoterms', typ: 'karte',
    frage: 'Wofür stehen die Incoterm-Gruppen E, F, C und D?',
    antwort: 'E – Abholklausel (EXW).\nF – Absendeklauseln OHNE Übernahme der Hauptfrachtkosten (FCA, FAS, FOB).\nC – Absendeklauseln MIT Übernahme der Kosten (CFR, CIF, CPT, CIP).\nD – Ankunftsklauseln (DAP, DPU, DDP).' },
  { id: 'mpa-in-06', fach: 'mpa', thema: 'Incoterms', typ: 'mc',
    frage: 'Bei welcher Klausel trägt der Verkäufer die geringsten Pflichten, weil er die Ware nur bei sich zur Abholung bereitstellt?',
    optionen: ['EXW (ab Werk)', 'DDP (geliefert verzollt)', 'CIF', 'FOB'],
    richtig: 0,
    erklaerung: 'Bei EXW geht die Gefahr direkt ab Werk des Exporteurs über, der Importeur transportiert auf eigene Kosten. Für den Verkäufer ist das die günstigste Klausel. DDP ist das Gegenstück: Der Verkäufer trägt alles inklusive Einfuhrverzollung.' },
  { id: 'mpa-in-07', fach: 'mpa', thema: 'Incoterms', typ: 'karte',
    frage: 'Prüfungsstil (F2020): Beschreibe EXW und FOB bezogen auf Kosten- und Gefahrenübergang.',
    antwort: 'EXW (Ab Werk): Der Verkäufer erfüllt seine Pflicht, wenn er die Ware zur vereinbarten Zeit bei sich (Werk, Lager) zur Abholung bereitstellt. Ab dann trägt der Käufer Kosten und Gefahr.\nFOB (Frei an Bord): Der Verkäufer liefert die Ware an Bord des vom Käufer benannten Schiffes im Verschiffungshafen und erledigt die Ausfuhrformalitäten. Ab „an Bord“ gehen Kosten und Gefahr auf den Käufer über; Einfuhrformalitäten und -abgaben trägt der Käufer.' },
  { id: 'mpa-in-08', fach: 'mpa', thema: 'Incoterms', typ: 'mc',
    frage: 'Was ist das Besondere an CIF gegenüber CFR?',
    optionen: ['Der Verkäufer schließt zusätzlich eine Transportversicherung zugunsten des Käufers ab', 'Die Gefahr geht erst im Bestimmungshafen über', 'Der Käufer zahlt die Seefracht', 'Der Verkäufer verzollt die Ware im Einfuhrland'],
    richtig: 0,
    erklaerung: 'Bei CFR und CIF zahlt der Verkäufer die Fracht bis zum Bestimmungshafen, die Gefahr geht aber schon über, wenn die Ware an Bord ist (wie bei FOB). Bei CIF kommt die Seeversicherung zugunsten des Käufers hinzu.' },
  { id: 'mpa-in-09', fach: 'mpa', thema: 'Incoterms', typ: 'karte',
    frage: 'Prüfungsstil (H2023): Was unterscheidet Einpunkt- und Zweipunktklauseln? Nenne je ein Beispiel.',
    antwort: 'Einpunktklausel: Kosten- und Gefahrenübergang am selben Punkt, z. B. FAS – Verkäufer zahlt und trägt das Risiko bis zur Längsseite des Schiffs im Verschiffungshafen, danach der Käufer.\nZweipunktklausel: Kosten- und Gefahrenübergang an verschiedenen Stellen, z. B. CIF – Verkäufer trägt die Kosten bis zum Bestimmungshafen (und versichert), das Risiko geht aber schon im Verschiffungshafen über.' },
  { id: 'mpa-in-10', fach: 'mpa', thema: 'Incoterms', typ: 'karte',
    frage: 'Wie unterscheiden sich DAP, DPU und DDP?',
    antwort: 'DAP (geliefert benannter Ort): Verkäufer stellt die Ware unentladen am Bestimmungsort bereit und trägt bis dahin Kosten und Gefahr.\nDPU (geliefert benannter Ort, entladen): wie DAP, zusätzlich entlädt der Verkäufer (z. B. am Terminal) – mehr Kosten und Risiko.\nDDP (geliefert verzollt): Verkäufer trägt alle Kosten der gesamten Strecke und die Einfuhrverzollung; der Käufer ist nur noch fürs Entladen zuständig.' },
  { id: 'mpa-in-11', fach: 'mpa', thema: 'Angebot', typ: 'karte',
    frage: 'Prüfungsstil (H2023): Wie kann man die Bindung an ein Angebot ausschließen? Nenne Freizeichnungsklauseln sowie Vor- und Nachteile.',
    antwort: 'Ein Angebot ist bindend (§ 145 BGB), außer die Bindung wird ausgeschlossen, z. B. durch „ohne Gewähr“ oder „freibleibend“ – dann ist es nur eine Aufforderung zur Abgabe eines Angebots.\nWeitere Klauseln: „solange Vorrat reicht“, Befristung der Bindung, Anpassung des Preises zum Liefertermin (Tagespreise, z. B. Gold), „Liefertermin vorbehalten“, unverbindlich, ohne Obligo.\nVorteile: mehr Sicherheit und Flexibilität für den Anbieter, schnellere Partnersuche, spätere Konkretisierung.\nNachteile: Kunden könnten wegen fehlender Mitsprache abspringen; Mehraufwand bei Änderungen.' },

  // ===== Wo. 09: Marktpositionierung und strategische Analyse =====
  { id: 'mpa-mp-01', fach: 'mpa', thema: 'Marktpositionierung', typ: 'karte',
    frage: 'Welche Elemente umfasst die Marktpositionierung laut Skript?',
    antwort: 'Marktpräsenz (Werbung, Service, Bekanntheitsgrad), Erscheinungsbild/Image/Corporate Identity, Gewinnung eines Marktanteils, Markenbildung, Preis, Qualität und eine Strategie der Differenzierung – z. B. Service, Zuverlässigkeit, Beschwerdemanagement, Beratung, Reparatur, Qualifikation der Mitarbeiter oder Produktdifferenzierung (Preis-Leistungs-Verhältnis, Ausstattung, Haltbarkeit, Styling, Entsorgung/Ökologie).' },
  { id: 'mpa-mp-02', fach: 'mpa', thema: 'Strategische Analyse', typ: 'mc',
    frage: 'Was gehört laut Skript NICHT zu den vier Instrumenten der strategischen Analyse?',
    optionen: ['Break-even-Analyse', 'Konkurrenzanalyse', 'Produktportfolio', 'Chancen-Risiken-Analyse'],
    richtig: 0,
    erklaerung: 'Die vier Instrumente sind Konkurrenzanalyse, Produktportfolio, Stärken-Schwächen-Analyse und Chancen-Risiken-Analyse.' },
  { id: 'mpa-mp-03', fach: 'mpa', thema: 'Konkurrenzanalyse', typ: 'karte',
    frage: 'Was ist eine Konkurrenzanalyse? Nenne Vor- und Nachteile.',
    antwort: 'Untersuchung der Wettbewerber, um Chancen und Risiken zu verstehen und die eigene Strategie zu verbessern.\nVorteile: Marktchancen erkennen, einzigartige Wettbewerbsvorteile (USP) entwickeln, Trends früh erkennen, Strategie durch Vergleich optimieren.\nNachteile: zeit- und ressourcenintensiv, muss laufend angepasst werden, vollständige und zuverlässige Infos über die Konkurrenz sind schwer zu bekommen.' },
  { id: 'mpa-mp-04', fach: 'mpa', thema: 'Konkurrenzpolitik', typ: 'karte',
    frage: 'Welche drei Strategien der Konkurrenzpolitik gibt es? Nenne je Beispiele.',
    antwort: 'Ausweichen: Nischenmärkte, einzigartige Angebote, Spezialisierung auf Zielgruppen, Standort oder Ladenkonzept optimieren.\nAbgrenzen: Differenzierung über den Preis (günstiger oder exklusiver), höhere Qualität, Zusatzleistungen (schneller Service, Beratung).\nBekämpfen: Marktanteile direkt auf Kosten der Konkurrenz – Preiskämpfe, intensive Werbung, Mitbewerber übernehmen, Exklusivverträge.' },
  { id: 'mpa-mp-05', fach: 'mpa', thema: 'Konkurrenzpolitik', typ: 'mc',
    frage: 'Ein Unternehmen schafft durch Innovation einen völlig neuen Markt ohne direkte Konkurrenz. Das ist eine …',
    optionen: ['Blue-Ocean-Strategie', 'Red-Ocean-Strategie', 'Abschöpfungsstrategie', 'Verdrängungsstrategie'],
    richtig: 0,
    erklaerung: 'Blue Ocean: neuer Markt, Wettbewerb bedeutungslos, höhere Gewinnpotenziale, starke Differenzierung. Red Ocean: bestehender Markt mit starker Konkurrenz, harter Verdrängungswettbewerb, geringe Margen, häufige Preiskämpfe.' },
  { id: 'mpa-mp-06', fach: 'mpa', thema: 'Produktportfolio', typ: 'karte',
    frage: 'Beschreibe die vier Felder des Produktportfolios (Marktwachstum / relativer Marktanteil).',
    antwort: 'Fragezeichen (hohes Wachstum, niedriger Anteil): verbrauchen mehr Cash als sie erzeugen; überleben nur, wenn sie mehr Marktanteil gewinnen.\nStars (hohes Wachstum, hoher Anteil): wachsen schnell, verbrauchen viel Cash, sind die Milchkühe von morgen.\nMilchkühe (niedriges Wachstum, hoher Anteil): Reife-/Sättigungsphase, hoher Deckungsbeitrag, Quelle für Gewinn und Liquidität.\nArme Hunde (niedriges Wachstum, niedriger Anteil): wenig Cash rein und raus (Cash-Fallen); vom Markt nehmen oder per Facelift zurückbringen (selektive Strategie).' },
  { id: 'mpa-mp-07', fach: 'mpa', thema: 'Produktportfolio', typ: 'mc',
    frage: 'Welche Produkte sind laut Skript die wichtigste Quelle für Gewinn und Liquidität?',
    optionen: ['Milchkühe', 'Stars', 'Fragezeichen', 'Arme Hunde'],
    richtig: 0,
    erklaerung: 'Milchkühe haben einen hohen relativen Marktanteil in einem kaum noch wachsenden Markt (Reife/Sättigung) und erbringen einen hohen Deckungsbeitrag. Stars verbrauchen noch viel Cash für ihr Wachstum.' },
  { id: 'mpa-mp-08', fach: 'mpa', thema: 'Stärken-Schwächen-Analyse', typ: 'karte',
    frage: 'Wie funktioniert die Stärken-Schwächen-Analyse laut Skript?',
    antwort: 'Merkmale (z. B. Technik, Forschung, Finanzkraft, Marktanteil, Standort, Kostenstruktur, Personal) erhalten einen Gewichtungsfaktor. Eigene Firma und Wettbewerber werden je Merkmal auf einer Skala von 1 (gering) bis 5 (hoch) bewertet, die gewichteten Punkte addiert (im Beispiel 470 zu 460). Das Profil zeigt, wo man stärker oder schwächer als der Wettbewerb ist.' },
  { id: 'mpa-mp-09', fach: 'mpa', thema: 'SWOT-Analyse', typ: 'karte',
    frage: 'Wofür stehen die vier Felder der SWOT-Analyse? Nenne je ein Beispiel aus dem Skript.',
    antwort: 'Strengths (Stärken, intern): z. B. erfahrene Führungskräfte, starke Markenidentität, effiziente Produktion.\nWeaknesses (Schwächen, intern): z. B. wenig Online-Präsenz, begrenzte Finanzen, Abhängigkeit von einem Lieferanten.\nOpportunities (Chancen, extern): z. B. wachsender Markt für umweltfreundliche Produkte, strategische Allianzen, Lockerung von Handelsbarrieren.\nThreats (Risiken, extern): z. B. neue Wettbewerber, steigende Rohstoffpreise, strengere Umweltgesetze.' },
  { id: 'mpa-mp-10', fach: 'mpa', thema: 'Marktsegmentierung', typ: 'karte',
    frage: 'Prüfungsstil (F2024): Beschreibe Segmentierungskriterien, um das Kaufverhalten einzuschätzen.',
    antwort: 'Geografisch (Stadt, Land): Aus welcher Region kommen die Kunden?\nSoziografisch (Einkommen, Vermögen, Beruf): finanzieller Hintergrund.\nDemografisch (Alter, Geschlecht, Familienstand).\nPsychografisch (Lebensstil, Einstellungen, z. B. Naturschutz).\nVerhaltensorientiert (Markentreue, Preisverhalten).' },
  { id: 'mpa-mp-11', fach: 'mpa', thema: 'Prüfungsaufgabe', typ: 'karte', art: 'rechnen',
    frage: 'Prüfungsstil (F2022): Ein Unternehmen verkauft 10.000 Zelte à 100 €; der Markt umfasst 10 Mio. €. Der Umsatz ist seit 2016 um 25 % gestiegen. Der größte Wettbewerber hatte 2016 einen Marktanteil von 20 % (Markt damals 5 Mio. €), 2021 von 5 %. Marktanteil und relativer Marktanteil 2016 und 2021?',
    antwort: 'Eigener Umsatz 2021 = 10.000 × 100 = 1.000.000 €; Marktanteil = 1.000.000 ÷ 10.000.000 × 100 = 10 %\nRelativer Marktanteil = eigener Umsatz ÷ Umsatz des größten Wettbewerbers × 100\n2016: eigener Umsatz 800.000 € (1 Mio. ÷ 1,25); Wettbewerber 20 % von 5 Mio. = 1.000.000 € → 80 %\n2021: Wettbewerber 5 % von 10 Mio. = 500.000 € → 200 %\n2016 Marktfolger (< 100 %), 2021 Marktführer (> 100 %) → Produkt fortführen.' },
  { id: 'mpa-mp-12', fach: 'mpa', thema: 'Produktportfolio', typ: 'karte',
    frage: 'Prüfungsstil (H2024): Nenne Kritikpunkte am McKinsey-Portfolio (Marktattraktivität / relative Wettbewerbsvorteile).',
    antwort: 'Vereinfachte Bewertung: nur zwei Dimensionen, wichtige Erfolgsfaktoren fehlen.\nStatische Analyse: Dynamik des Marktes und künftige Entwicklungen (Technologie, Regulierung) werden nicht berücksichtigt.\nVernachlässigt strategische Aspekte wie Markteintrittsbarrieren, Innovationen, Partnerschaften.\nKundenbedürfnisse und -präferenzen werden kaum einbezogen.' },
  { id: 'mpa-mp-13', fach: 'mpa', thema: 'Produktportfolio', typ: 'karte',
    frage: 'Prüfungsstil (H2024): Welche Marketingstrategien empfiehlt die Lösung im McKinsey-Portfolio für (1) hohe Attraktivität und Potenzial, (2) hohe Attraktivität bei geringen Wettbewerbsvorteilen, (3) geringe Attraktivität und geringe Vorteile?',
    antwort: '(1) Schlafsäcke: Ausgleichsstrategie (Blue Ocean) – durch Weiterentwicklung und Innovation weitere Wettbewerbsvorteile erzielen, fördert das Wachstum.\n(2) Camping-Zelte: Anpassungsstrategie – erst ans Marktniveau anpassen, dann Ausgleichsstrategie.\n(3) Gas- und Benzinkocher: Desinvestitionsstrategie – keine Marketingaktivitäten mehr, Mittel auf attraktivere Produkte lenken.' },

  // ===== Wo. 09: Marketing =====
  { id: 'mpa-mk-01', fach: 'mpa', thema: 'Marketingkonzepte', typ: 'karte',
    frage: 'Nenne die fünf klassischen Marketingkonzepte mit Leitgedanke.',
    antwort: 'Produktionskonzept: Kunden wollen verfügbare, günstige Produkte → Massenproduktion, niedrige Kosten (Kritik: ignoriert Kundenwünsche).\nProduktkonzept: Kunden wollen höchste Qualität und Innovation (Kritik: „besser“ ist nicht automatisch „gewünscht“).\nVerkaufskonzept: Kunden müssen durch Werbung und Verkaufsdruck überzeugt werden (Kritik: kurzfristig, keine Bindung).\nMarketingkonzept i. e. S.: Kundenbedürfnisse im Mittelpunkt – modernes Grundverständnis, Basis für Kreislauf und Marketing-Mix.\nSoziales Marketingkonzept: zusätzlich gesellschaftliche Interessen (Nachhaltigkeit, faire Lieferketten).' },
  { id: 'mpa-mk-02', fach: 'mpa', thema: 'Marketingkonzepte', typ: 'mc',
    frage: '„Jeder Kunde kann ein Auto in jeder Farbe haben – solange es schwarz ist.“ Welches Marketingkonzept zeigt dieses Beispiel?',
    optionen: ['Produktionskonzept', 'Produktkonzept', 'Verkaufskonzept', 'Soziales Marketingkonzept'],
    richtig: 0,
    erklaerung: 'Beim Produktionskonzept stehen Effizienz, Massenproduktion und niedrige Kosten im Vordergrund. Kritik: Die Bedürfnisse und Wünsche der Kunden werden vernachlässigt.' },
  { id: 'mpa-mk-03', fach: 'mpa', thema: 'Marketingkreislauf', typ: 'karte',
    frage: 'Beschreibe den Marketingkreislauf und die Phasen der Marketingplanung.',
    antwort: 'Kreislauf: Marktforschung → Marketingziele → Einsatz der Marketinginstrumente → Durchführung (Marketing-Mix) → Marketingkontrolle (Umsatz, Kosten, Abläufe, Handelsspanne) → wieder Marktforschung.\nPlanung: strategisch (langfristiges Konzept) und operativ (kurzfristiger Einsatz der Instrumente). Phasen: Problemerkennung, Daten sammeln (Marktforschung), Ist-Analyse, Soll-Konzept, Entscheidung durch das Management, Realisierung, Kontrolle.' },
  { id: 'mpa-mk-04', fach: 'mpa', thema: 'PESTLE', typ: 'karte',
    frage: 'Wofür steht PESTLE, und wofür wird die Analyse genutzt?',
    antwort: 'Political (politisch), Economic (wirtschaftlich), Social (soziokulturell), Technological (technologisch), Legal (rechtlich), Environmental (ökologisch).\nAnalyseinstrument für das internationale Marketing bzw. zur Erhebung der Marktbedingungen.' },
  { id: 'mpa-mk-05', fach: 'mpa', thema: 'Marketingziele', typ: 'karte',
    frage: 'Unterscheide strategische und operative Marketingziele mit Beispielen.',
    antwort: 'Strategisch (langfristig): Absatzsteigerung, Marktanteil erhöhen, Gewinnsteigerung, Kundenzufriedenheit und -bindung, Image und Markenbekanntheit.\nOperativ (kurz- bis mittelfristig, konkret und messbar): z. B. 20 % mehr Website-Besucher in 6 Monaten, Conversion Rate 5 %, 1.000 neue Newsletter-Abonnenten pro Monat, Produkteinführung bis Q3.' },
  { id: 'mpa-mk-06', fach: 'mpa', thema: 'Marktforschung', typ: 'karte',
    frage: 'Wie gliedern sich die Methoden der Marktforschung?',
    antwort: 'Primärforschung (eigene Erhebung): Auswahlverfahren – Befragung, Beobachtung, Experiment/Test; Erhebungsart – Vollerhebung, Teilerhebung, Quotenverfahren, Randomverfahren, Panelverfahren.\nSekundärforschung: Auswertung vorhandener interner oder externer Daten.' },
  { id: 'mpa-mk-07', fach: 'mpa', thema: 'Marktforschung', typ: 'mc',
    frage: 'Bei welchem Verfahren hat jedes Element der Grundgesamtheit die gleiche Chance, in die Stichprobe zu kommen?',
    optionen: ['Randomverfahren', 'Quotenverfahren', 'Panelverfahren', 'Vollerhebung'],
    richtig: 0,
    erklaerung: 'Randomverfahren: zufällig und repräsentativ, aber aufwendig und teuer. Quotenverfahren: Stichprobe bildet bestimmte Merkmale nach (z. B. 50 % Frauen) – schneller und günstiger, aber mögliche Verzerrungen.' },
  { id: 'mpa-mk-08', fach: 'mpa', thema: 'Marktforschung', typ: 'karte',
    frage: 'Was ist das Panelverfahren? Nenne Vor- und Nachteile.',
    antwort: 'Dieselbe Personengruppe wird über längere Zeit regelmäßig zum selben Thema befragt (Längsschnittanalyse).\nVorteile: zeigt Entwicklungen und Trends, Veränderungen statt Momentaufnahme, hohe Datenkontinuität.\nNachteile: Teilnehmer fallen aus (Umzug, Krankheit), nachlassende Motivation (Paneleffekt), unzuverlässige Antworten durch Gewöhnung.' },
  { id: 'mpa-mk-09', fach: 'mpa', thema: 'Marktforschung', typ: 'karte',
    frage: 'Prüfungsstil (H2022): Warum empfiehlt die Lösung für einen neuen Geschäftsbereich (Wallboxen) die primäre Marktforschung?',
    antwort: 'Sie liefert konkrete, auf die eigene Fragestellung zugeschnittene Informationen, die nur dem Unternehmen vorliegen (Wettbewerbsvorteil); ermöglicht eine kundenspezifische Produktgestaltung; senkt das Risiko von Fehleinschätzungen (Flops); Ergebnisse können später weiterverwendet werden (Zweitverwertung, z. B. für Töchter).\nAls Analyseinstrument für die Marktbedingungen: PESTLE.' },
  { id: 'mpa-mk-10', fach: 'mpa', thema: 'Marketing-Mix', typ: 'mc',
    frage: 'Welcher Begriff ist laut Skript ein anderer Name für die Preispolitik?',
    optionen: ['Kontrahierungspolitik', 'Distributionspolitik', 'Kommunikationspolitik', 'Sortimentspolitik'],
    richtig: 0,
    erklaerung: 'Die 4 P: Product → Produktpolitik, Price → Preis- bzw. Kontrahierungspolitik, Place → Distributionspolitik, Promotion → Kommunikationspolitik.' },
  { id: 'mpa-mk-11', fach: 'mpa', thema: 'Produktpolitik', typ: 'karte',
    frage: 'Welche Elemente gehören zur Produktpolitik?',
    antwort: 'Produktgestaltung (Aussehen, Qualität, Funktion), Sortiment (welche Produkte, welche Varianten), Markenpolitik, Service (Garantie, Reparatur) und die Anpassung im Produktlebenszyklus.\nMerksatz: Was bieten wir an – und in welcher Form?' },
  { id: 'mpa-mk-12', fach: 'mpa', thema: 'Preispolitik', typ: 'karte',
    frage: 'Welche Elemente gehören zur Preispolitik?',
    antwort: 'Preisfestsetzung; Preisdifferenzierung (nach Zielgruppe, Region, Zeit, Menge); psychologische Preise (9,99 statt 10); Konditionenpolitik (Rabatte, Skonto, Ratenzahlung, Zahlungsfristen); Preisstrategien: Niedrigpreis (Discounter), Hochpreis (Luxusmarken), Skimming (erst hoch, dann Senkung).\nMerksatz: Was kostet das Produkt – und welche Zusatzbedingungen gelten?' },
  { id: 'mpa-mk-13', fach: 'mpa', thema: 'Preispolitik', typ: 'karte',
    frage: 'Prüfungsstil (F2020): Was ist Preisdifferenzierung, welche Voraussetzungen braucht sie, und welche Formen gibt es?',
    antwort: 'Das gleiche Produkt wird zu unterschiedlichen Preisen verkauft.\nVoraussetzungen: unterschiedliche Bedarfssituationen in den Märkten, keine Verbindung zwischen den Märkten und zwischen den Abnehmern.\nFormen: räumlich (Regionen/Länder), quantitativ (Staffelpreise je Menge), abnehmer-/verwendungsorientiert (nach Branche), zeitlich (nach Nachfrage), anlassbezogen (z. B. Messepreise).' },
  { id: 'mpa-mk-14', fach: 'mpa', thema: 'Distributionspolitik', typ: 'karte',
    frage: 'Welche Elemente gehören zur Distributionspolitik?',
    antwort: 'Absatzwege: direkter Vertrieb (ohne Zwischenhändler, z. B. eigener Online-Shop) und indirekter Vertrieb (Händler, Großhändler, Plattformen).\nLogistik: Transport, Lagerhaltung, Lieferzeiten, Versandkosten, Verpackung, Retouren.\nStandortwahl und Vertriebsorganisation (Verkaufsabteilung, Außendienst, Online).\nMerksatz: Wie kommt das Produkt zum Kunden?' },
  { id: 'mpa-mk-15', fach: 'mpa', thema: 'Kommunikationspolitik', typ: 'karte',
    frage: 'Welche Instrumente gehören zur Kommunikationspolitik?',
    antwort: 'Werbung (TV, Plakate, Online-Anzeigen, Social Media), Verkaufsförderung (Rabatte, Gutscheine, Produktproben), Public Relations (Pressearbeit, Sponsoring, soziale Projekte), persönlicher Verkauf (Beratung, Außendienst), Online-Kommunikation (Influencer, E-Mail-Marketing, Website).\nMerksatz: Wie sprechen wir mit unseren Kunden?' },
  { id: 'mpa-mk-16', fach: 'mpa', thema: 'Werbung', typ: 'karte',
    frage: 'Nenne die Elemente einer Werbemaßnahme mit Leitfrage.',
    antwort: 'Werbetreibender – Wer? (werbendes Unternehmen)\nWerbeobjekt – Was? (Produkt, Sortiment, Unternehmen)\nWerbesubjekt – Wem? (Umworbener)\nWerbeträger – Womit? (Medium, z. B. Fernsehen, Print)\nWerbemittel – Wie? (Fernsehspot, Anzeige)\nWerbebotschaft – Was? (Inhalt, Aussage, z. B. „Trink Dich Frisch!“)' },
  { id: 'mpa-mk-17', fach: 'mpa', thema: 'Werbung', typ: 'mc',
    frage: 'Ein Fernsehspot ist laut Skript ein …',
    optionen: ['Werbemittel', 'Werbeträger', 'Werbesubjekt', 'Werbeobjekt'],
    richtig: 0,
    erklaerung: 'Das Werbemittel beantwortet „Wie?“ (Spot, Anzeige). Der Werbeträger ist das Medium („Womit?“, z. B. das Fernsehen). Das Werbesubjekt ist der Umworbene, das Werbeobjekt das beworbene Produkt.' },
  { id: 'mpa-mk-18', fach: 'mpa', thema: 'Markenpolitik', typ: 'karte',
    frage: 'Prüfungsstil (H2023/H2021): Erkläre Einzel-, Familien- und Dachmarke.',
    antwort: 'Einzelmarke (Monomarke): eine Marke nur für ein Produkt, das Unternehmen tritt in den Hintergrund – stellt die Einmaligkeit heraus.\nFamilienmarke: mehrere Produkte einer Produktgruppe unter einer (meist Fantasie-)Marke; Einzelprodukte tragen eine Submarke.\nDachmarke: fasst unter dem Herstellernamen verschiedene Produkte zusammen, die eigene Submarken tragen (z. B. Dachmarke „Hersteller“, Submarke „Modell e“) – das Image überträgt sich auf neue Produkte.' },
  { id: 'mpa-mk-19', fach: 'mpa', thema: 'Marketingstrategien', typ: 'karte',
    frage: 'Prüfungsstil (F2023): Nenne Marketingstrategien, um neue Marktchancen zu finden.',
    antwort: 'Fokussierung (Nischenstrategie), Kostenführerschaft (günstig produzieren und anbieten), Differenzierung bzw. Qualitätsführerschaft (hochwertige Materialien, EFQM), Marktdurchdringung (bestehendes Produkt verstärkt bewerben), Marktentwicklung (neuer Absatzmarkt, z. B. Ausland), Produktentwicklung (neue Produkte), Diversifikation (z. B. zusätzlich Rasenmäh-Roboter).\nZur Kostenführerschaft passt die Niedrigpreisstrategie.' },
  { id: 'mpa-mk-20', fach: 'mpa', thema: 'Marketingplanung', typ: 'karte',
    frage: 'Prüfungsstil (H2023): Beschreibe je einen Aspekt der strategischen, taktischen und operativen Marketingplanung für ein neues Produkt.',
    antwort: 'Strategisch: Das Produkt muss zur Unternehmensphilosophie bzw. zum Leitbild passen.\nTaktisch: Es muss in den bestehenden Marketing-Mix integrierbar sein; Beginn der Maßnahmen und verfügbares Budget beachten.\nOperativ: Umsetzung und Kontrolle – trägt das Produkt z. B. zur Auslastung bei und passt es ins Leitbild und den Marketing-Mix?' },
  { id: 'mpa-mk-21', fach: 'mpa', thema: 'Marketing-Mix', typ: 'karte',
    frage: 'Prüfungsstil (H2021): Erstelle einen Marketing-Mix für eine technikaffine Zielgruppe mit hoher Kaufkraft (neue E- und Wasserstoff-Fahrzeuge).',
    antwort: 'Produkt: Namen, die zur neuen Technik passen; modernes Design.\nDistribution: Verkauf und Service getrennt von den Verbrennern; eigene Internetseite.\nKontrahierung: Hochpreisstrategie; Kreditangebote; kostenlose Anlieferung.\nKommunikation: Werbung in sozialen Medien, TV im Umfeld von Auto-Reportagen, PR für ein passendes Image.' },
  { id: 'mpa-mk-22', fach: 'mpa', thema: 'E-Business', typ: 'karte',
    frage: 'Welche Bereiche umfasst E-Business?',
    antwort: 'E-Commerce: elektronischer Handel – internetbasierte Zusammenarbeit entlang der gesamten Wertschöpfungskette.\nE-Banking: elektronischer Zahlungsverkehr (Homebanking).\nE-Procurement: elektronische Beschaffung von Gütern und Dienstleistungen.\nE-Logistik: IT-gestützte Planung und Steuerung logistischer Prozesse.' },
  { id: 'mpa-mk-23', fach: 'mpa', thema: 'E-Business', typ: 'mc',
    frage: 'Eine Firma kauft Roh-, Hilfs- und Betriebsstoffe online bei einer anderen Firma. Welche Beziehung ist das?',
    optionen: ['B2B', 'B2C', 'C2B', 'B2A'],
    richtig: 0,
    erklaerung: 'B2B = Unternehmen und Unternehmen. B2C = Unternehmen verkauft an Privatleute, C2B = Privatperson kauft bei einem Unternehmen (laut Skript-Tabelle), B2A = Unternehmen und Behörden (z. B. Umsatzsteuererklärung).' },
  { id: 'mpa-mk-24', fach: 'mpa', thema: 'E-Business', typ: 'karte',
    frage: 'Was gehört laut Skript zum E-Procurement?',
    antwort: 'Kanäle: Internet, Intranet, Extranet, Medien.\nInternet-Dienstleister (Informationsbroker, Einkaufsdienstleister, Softwareprovider), virtuelle Marktplätze (elektronische Kataloge, Börsen, Auktionen, Online-Ausschreibungen), Logistikprozesse (Einkaufs-Webseiten, Bestellabwicklung, Datenaustausch), Informationsmanagement (Einkaufsportale, Internet-Kommunikation, Marktrecherchen).' },
  { id: 'mpa-mk-25', fach: 'mpa', thema: 'Prüfungsaufgabe', typ: 'karte',
    frage: 'Prüfungsstil (F2021, MPA-Skript): Nenne Argumente gegen und für Flächentarifverträge, Möglichkeiten der Flexibilisierung und die Idee der produktivitätsorientierten Lohnpolitik.',
    antwort: 'Dagegen: gilt auch für Betriebe, die dadurch besonders belastet werden; Arbeitszeitregeln passen nicht zu Produktionsablauf oder Auftragslage.\nDafür: sozialer Friede und Gerechtigkeit durch einheitliche Vergütung; Rechtssicherheit für beide Seiten.\nFlexibilisierung: Betriebsvereinbarungen (Arbeitszeit, Entlohnung); tarifliche Öffnungsklauseln.\nProduktivitätsorientiert: Lohnerhöhungen im Rahmen des Produktivitätsfortschritts führen zu keiner Kostensteigerung und verschlechtern die Wettbewerbsposition nicht.' },
);
